def reflex_vacuum_agent(location, status):
    if status == 'DIRTY':
        return 'CLEAN'
    elif location == 'A':
        return 'RIGHT'
    elif location == 'B':
        return 'LEFT'

events = [('A', 'DIRTY'), ('A', 'CLEAN'), ('B', 'DIRTY'), ('B', 'CLEAN')]
results = [reflex_vacuum_agent(loc, st) for loc, st in events]
print(results)
